449 |     /* @notice Sets fuses of a name that you own the parent of. Can also be called by the owner of a .eth name
450 |      * @param parentNode parent namehash of the name e.g. vitalik.xyz would be namehash('xyz')
451 |      * @param labelhash labelhash of the name, e.g. vitalik.xyz would be keccak256('vitalik')
452 |      * @param fuses fuses to burn
453 |      * @param expiry when the fuses will expire
454 |      */
455 | 
456 |     function setChildFuses(
457 |         bytes32 parentNode,
458 |         bytes32 labelhash,
459 |         uint32 fuses,
460 |         uint64 expiry
461 |     ) public {
462 |         bytes32 node = _makeNode(parentNode, labelhash);
463 |         (address owner, uint32 oldFuses, uint64 oldExpiry) = getData(
464 |             uint256(node)
465 |         );
466 |         uint64 maxExpiry;
467 |         if (parentNode == ETH_NODE) {
468 |             if (!isTokenOwnerOrApproved(node, msg.sender)) {
469 |                 revert Unauthorised(node, msg.sender);
470 |             }
471 |             // max expiry is set to the expiry on the registrar
472 |             maxExpiry = uint64(registrar.nameExpires(uint256(labelhash)));
473 |         } else {
474 |             if (!isTokenOwnerOrApproved(parentNode, msg.sender)) {
475 |                 revert Unauthorised(node, msg.sender);
476 |             }
477 | 
478 |             // max expiry is set to the expiry of the parent
479 |             (, , maxExpiry) = getData(uint256(parentNode));
480 |         }
481 | 
482 |         expiry = _normaliseExpiry(expiry, oldExpiry, maxExpiry);
483 | 
484 |         // if PARENT_CANNOT_CONTROL has been burned and fuses have changed
485 |         if (
486 |             oldFuses & PARENT_CANNOT_CONTROL != 0 &&
487 |             oldFuses | fuses != oldFuses
488 |         ) {
489 |             revert OperationProhibited(node);
490 |         }
491 |         fuses |= oldFuses;
492 |         _setFuses(node, owner, fuses, expiry);
493 |     }
